   449→#[cfg(test)]
   450→mod reference_implementation {
   451→    //! Reference implementation for validating COLMAP intrinsics parsing
   452→    //!
   453→    //! This serves as documentation for the expected precision and behavior.
   454→
   455→    use nalgebra::{Matrix3, Vector3};
   456→
   457→    /// Expected precision for intrinsic parameters
   458→    pub const FOCAL_LENGTH_PRECISION: f32 = 0.01; // pixels
   459→    pub const PRINCIPAL_POINT_PRECISION: f32 = 0.01; // pixels
   460→
   461→    /// Expected precision for extrinsic parameters
   462→    pub const ROTATION_PRECISION_DEGREES: f32 = 0.1; // degrees
   463→    pub const TRANSLATION_PRECISION: f32 = 0.001; // units
   464→
   465→    /// Verify intrinsics meet precision requirements
   466→    pub fn verify_intrinsics_precision(
   467→        parsed_fx: f32,
   468→        parsed_fy: f32,
   469→        parsed_cx: f32,
   470→        parsed_cy: f32,
   471→        ground_truth_fx: f32,
   472→        ground_truth_fy: f32,
   473→        ground_truth_cx: f32,
   474→        ground_truth_cy: f32,
   475→    ) -> bool {
   476→        let fx_error = (parsed_fx - ground_truth_fx).abs();
   477→        let fy_error = (parsed_fy - ground_truth_fy).abs();
   478→        let cx_error = (parsed_cx - ground_truth_cx).abs();
   479→        let cy_error = (parsed_cy - ground_truth_cy).abs();
   480→
