   121→
   122→    for _ in 0..num_cameras {
   123→        let camera_id = reader.read_u32::<LittleEndian>()?;
   124→        let model_id = reader.read_i32::<LittleEndian>()?;
   125→        let width = reader.read_u64::<LittleEndian>()?;
   126→        let height = reader.read_u64::<LittleEndian>()?;
   127→
   128→        // Parse parameters based on camera model
   129→        // Model IDs: 0=SIMPLE_PINHOLE, 1=PINHOLE, 2=SIMPLE_RADIAL, 3=RADIAL, etc.
   130→        let camera = match model_id {
   131→            0 => {
   132→                // SIMPLE_PINHOLE: f, cx, cy
   133→                let f = reader.read_f64::<LittleEndian>()? as f32;
   134→                let cx = reader.read_f64::<LittleEndian>()? as f32;
   135→                let cy = reader.read_f64::<LittleEndian>()? as f32;
   136→
   137→                Camera::new(
   138→                    f,
   139→                    f, // fx = fy for simple pinhole
   140→                    cx,
   141→                    cy,
   142→                    width as u32,
   143→                    height as u32,
   144→                    Matrix3::identity(), // Will be filled from images.bin
   145→                    Vector3::zeros(),
   146→                )
   147→            }
