   156→                    fx,
   157→                    fy,
   158→                    cx,
   159→                    cy,
   160→                    width as u32,
   161→                    height as u32,
   162→                    Matrix3::identity(),
   163→                    Vector3::zeros(),
   164→                )
   165→            }
