   176→                    reader.read_f64::<LittleEndian>()?;
   177→                }
   178→
   179→                Camera::new(
   180→                    f,
   181→                    f, // fy = fx for radial models
   182→                    cx,
   183→                    cy,
   184→                    width as u32,
   185→                    height as u32,
   186→                    Matrix3::identity(),
   187→                    Vector3::zeros(),
   188→                )
   189→            }
   190→            4 => {
   191→                // OPENCV: fx, fy, cx, cy, k1, k2, p1, p2
   192→                has_distortion_models = true;
