   239→        };
   240→
   241→        cameras.insert(camera_id, camera);
   242→    }
   243→
   244→    // Warn if distortion parameters were ignored
   245→    if has_distortion_models {
   246→        eprintln!();
   247→        eprintln!("⚠️  WARNING: COLMAP distortion parameters ignored");
   248→        eprintln!("   Detected non-pinhole camera models (RADIAL, OPENCV, or FISHEYE).");
